function _runGitDiff(baseRef, headRef, workingDir) {
    var variants = [
        'git diff ' + baseRef + '...' + headRef,
        'git diff origin/' + baseRef + '...' + headRef,
        'git diff origin/' + baseRef + '...origin/' + headRef
