            return segment && segment[0] !== '.';
        }) &&
        /^[A-Za-z0-9._/-]+$/.test(path);
}

function isSafeRefName(ref) {
    return ref &&
        typeof ref === 'string' &&
        ref[0] !== '-' &&
        ref.indexOf('..') === -1 &&
        /^[A-Za-z0-9._/-]+$/.test(ref);
}

function isSafeSubmoduleFilePath(path) {
    return path &&
        typeof path === 'string' &&
        path[0] !== '/' &&
        path[0] !== '-' &&
        path.indexOf('..') === -1 &&
        path.split('/').every(function(segment) { return segment; }) &&
