        console.warn('github_get_pr_review_threads failed (falling back to conversations-only inventory):', e.message || e);
    }
    var inv = _githubCollectThreadInventory(conversations, graphqlRaw);
    if (!inv) return null;
    var rawThreads = inv.threads;
