    }

    var descendantSha = cleanOutput(run('git -C ' + path + ' rev-parse ' + descendant) || '').trim().split(/\r?\n/).pop();
    if (!descendantSha) {
        throw new Error('Could not resolve managed submodule descendant ref for ' + path + ': ' + descendant);
