    run('git -C ' + path + ' push origin HEAD:' + branch);
    console.log('Managed submodule pushed:', path, '-> origin/' + branch);

    if (tagPrefix) {
        publishSubmoduleTag(run, cleanOutput, path, tagPrefix);
    }
}

