suite('pullRequest helper > createPullRequest branches (gh-1041)', function() {

    test('requires branchName before either creation path runs', function() {
        var pr = loadPullRequestHelper();
        var scmCalled = false;

        var result = pr.createPullRequest({
            title: 'x',
